"""Build the self-contained entry point from the platform helpers."""
from pathlib import Path
root = Path(__file__).resolve().parents[1]
openwrt = (root / 'openwrt' / 'dns.sh').read_text(encoding='utf-8').split('\n', 1)[1]
linux = (root / 'linux' / 'dns.sh').read_text(encoding='utf-8').split('\n', 1)[1]
output = '''#!/bin/sh
# Generated by tools/build-dns.py; edit the platform helpers, then rebuild.
if command -v uci >/dev/null 2>&1 && [ -f /etc/openwrt_release ]; then
''' + openwrt + '\nexit 0\nfi\n' + linux
(root / 'dns.sh').write_bytes(output.encode('utf-8'))
